def amicable_numbers_sum(limit):
    d = [1] * (limit + 1)
    for i in range(2, limit // 2 + 1):
        for j in range(i * 2, limit + 1, i):
            d[j] += i
    return sum(n for n in range(2, limit + 1) if d[n] != n and (p := d[n]) <= limit and d[p] == n)
